#!/usr/bin/env node
// =====================================================================
// Track D drift-check - frontend side
//
// Compares src/lib/permissions.ts against a snapshot of the backend
// Permissions.cs (backend-permissions-snapshot.json, generated by
// dump-permissions.ps1 on the backend and copied over manually - there's
// no live cross-machine link, so the snapshot can go stale; regenerate
// it whenever Permissions.cs changes and re-run this check before
// trusting the result).
//
// Exit code: 0 = no drift, 1 = drift found, 2 = setup error.
// =====================================================================

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const PERMISSIONS_TS_PATH = path.join(__dirname, "..", "src", "lib", "permissions.ts");
const SNAPSHOT_PATH = path.join(__dirname, "backend-permissions-snapshot.json");

// Prefixes intentionally excluded from the admin frontend. Portal.* gates
// the ESS portal backend, not the admin app, even though both share the
// same API and permissions table (decided during Track D).
const EXCLUDED_PREFIXES = ["Portal."];

function extractKeysFromTs(text) {
  // Matches quoted dotted strings like "Module.Feature.Action" - same
  // pattern used to verify permissions.ts during the Track D audit.
  const re = /"([A-Za-z0-9]+(?:\.[A-Za-z0-9]+)+)"/g;
  const keys = new Set();
  let m;
  while ((m = re.exec(text)) !== null) {
    keys.add(m[1]);
  }
  return keys;
}

function main() {
  if (!fs.existsSync(PERMISSIONS_TS_PATH)) {
    console.error(`permissions.ts not found at ${PERMISSIONS_TS_PATH}`);
    console.error("Edit PERMISSIONS_TS_PATH at the top of this script if your path differs.");
    process.exit(2);
  }

  if (!fs.existsSync(SNAPSHOT_PATH)) {
    console.error(`Backend snapshot not found at ${SNAPSHOT_PATH}`);
    console.error("Run dump-permissions.ps1 on the backend and copy the output here first.");
    process.exit(2);
  }

  const tsText = fs.readFileSync(PERMISSIONS_TS_PATH, "utf8");
  const frontendKeys = extractKeysFromTs(tsText);

  const backendAll = JSON.parse(fs.readFileSync(SNAPSHOT_PATH, "utf8"));
  const backendKeys = new Set(
    backendAll.filter((k) => !EXCLUDED_PREFIXES.some((p) => k.startsWith(p)))
  );

  const missingFromFrontend = [...backendKeys].filter((k) => !frontendKeys.has(k)).sort();
  const phantomInFrontend = [...frontendKeys].filter((k) => !backendKeys.has(k)).sort();

  console.log(`Backend keys (snapshot, after exclusions): ${backendKeys.size}`);
  console.log(`Frontend keys found in permissions.ts:     ${frontendKeys.size}`);

  let hasDrift = false;

  if (missingFromFrontend.length > 0) {
    hasDrift = true;
    console.log(`\nMISSING FROM permissions.ts (${missingFromFrontend.length}):`);
    for (const k of missingFromFrontend) console.log(`  - ${k}`);
  }

  if (phantomInFrontend.length > 0) {
    hasDrift = true;
    console.log(`\nPHANTOM IN permissions.ts (${phantomInFrontend.length}) - no backend counterpart:`);
    for (const k of phantomInFrontend) console.log(`  - ${k}`);
  }

  if (hasDrift) {
    console.log("\nDrift detected. Reconcile permissions.ts against Permissions.cs before merging.");
    console.log("(If the snapshot itself is stale, regenerate it first - see the header comment.)");
    process.exit(1);
  }

  console.log("\nNo drift. permissions.ts matches the backend snapshot.");
  process.exit(0);
}

main();
